    private async Task<IReadOnlyList<SubmittedJob>> MakeJobsAsync(
        Message message,
        IReadOnlyList<RuleHit> hits,
        ModelPreparation preparation,
        CancellationToken cancellationToken)
    {
        var response = preparation.Response;
        if (response is null)
        {
            var failed = await NewJobAsync(message, hits, null, cancellationToken);
            PrepareJob.RecordFailure(failed, preparation, _clock.UtcNow);
            return new[] { new SubmittedJob(failed.Id, failed.Reference, false) };
        }

        if (response.Issues.Count == 0)
        {
            var flagged = await NewJobAsync(message, hits, null, cancellationToken);
            PrepareJob.RecordNotMaintenance(flagged, preparation, _clock.UtcNow);
            return new[] { new SubmittedJob(flagged.Id, flagged.Reference, false) };
        }

        var resolver = new PropertyResolver(await _properties.ListAsync(cancellationToken));
        var matches = response.Issues.Select(i => resolver.Resolve(i.PropertyText)).ToList();
        var propertyIds = matches.Where(m => m.IsResolved).Select(m => m.Property!.Id).Distinct().ToList();
        var candidates = propertyIds.Count == 0
            ? Array.Empty<Job>()
            : await _jobs.ListOpenAtPropertiesAsync(
                propertyIds,
                message.ReceivedAtUtc - FollowUpMatcher.Window,
                cancellationToken);

        var result = new List<SubmittedJob>();
        var followUps = new Dictionary<Job, Urgency>();
        for (var index = 0; index < response.Issues.Count; index++)
        {
            var issue = response.Issues[index];
            var property = matches[index];
            var category = PrepareJob.CategoryFor(issue, property);

            // Only jobs that existed before this message are candidates: the model's split stands within a message.
            var existing = FollowUpMatcher.Match(candidates, property.Property?.Id, category, message.ReceivedAtUtc);
            if (existing is not null)
            {
                followUps[existing] = followUps.TryGetValue(existing, out var raised) && raised > issue.Urgency
                    ? raised
                    : issue.Urgency;
                result.Add(new SubmittedJob(existing.Id, existing.Reference, true));
                continue;
            }

            var job = await NewJobAsync(message, hits, property.Property?.Id, cancellationToken);
            PrepareJob.RecordIssue(job, preparation, index, property, _clock.UtcNow);
            result.Add(new SubmittedJob(job.Id, job.Reference, false));
        }

        foreach (var (job, urgency) in followUps)
        {
            job.AttachFollowUp(message, urgency, _clock.UtcNow);
            job.ApplyRules(hits, _clock.UtcNow);
        }

        // Two issues attached to the same job are one follow-up.
        return result.DistinctBy(j => j.JobId).ToList();
    }

    private async Task<Job> NewJobAsync(Message message, IReadOnlyList<RuleHit> hits, Guid? propertyId, CancellationToken cancellationToken)
    {
        var number = await _jobs.NextJobNumberAsync(cancellationToken);
        var job = Job.CreateFromMessage(message, JobReference.FromNumber(number), _clock.UtcNow, propertyId);
        job.ApplyRules(hits, _clock.UtcNow);
        _jobs.Add(job);
        return job;
    }
}

using Meridian.Application.Templates;
using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Meridian.Domain.Outbox;

namespace Meridian.Application.Outbox;

/// <summary>
/// The acknowledgement step of the pipeline (AD-3, R16): after the emergency rules and before the model, the sender of
/// an incoming message gets one fixed message quoting the job reference. When the gas or carbon-monoxide rule has
/// fired on the job, that message is the gas safety message instead of the ordinary acknowledgement (RULE-6). Plain
/// code, no model call; the body is a template with only the reference filled in (AD-7).
/// </summary>
public sealed class AcknowledgeTenant
{
    private readonly IOutbox _outbox;

    public AcknowledgeTenant(IOutbox outbox)
    {
        _outbox = outbox;
    }

    /// <summary>
    /// Writes the acknowledgement for <paramref name="message"/> to the outbox and records
    /// <see cref="EventType.AcknowledgementSent"/> on <paramref name="job"/>. Call once per incoming message, inside
    /// the same unit of work as the message and the rules, after <see cref="Job.ApplyRules"/>.
    /// </summary>
    public OutboundMessage Send(Job job, Message message, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(job);
        ArgumentNullException.ThrowIfNull(message);

        var templateId = TenantTemplates.AcknowledgementFor(job.RuleIds);
        var body = TenantTemplates.Render(templateId, job.Reference);
        var outbound = _outbox.Send(
            new OutboundRequest(job.Id, OutboundChannels.Email, message.Sender, templateId, body),
            nowUtc);
        job.RecordAcknowledgement(outbound.Id, templateId, nowUtc);
        return outbound;
    }
}
using Meridian.Domain.Outbox;

namespace Meridian.Application.Outbox;

/// <summary>What to send: the job, channel, recipient and the already-rendered template body (AD-7).</summary>
public sealed record OutboundRequest(Guid JobId, string Channel, string Recipient, string TemplateId, string Body);

/// <summary>
/// The outbox port (AD-8). Every acknowledgement, notification and contractor message goes through it. The first
/// version's adapter only stores the row (status <see cref="OutboundStatus.Simulated"/>); nothing is really sent.
/// </summary>
public interface IOutbox
{
    /// <summary>
    /// Writes the message to the outbox. Call inside a unit of work: the row is saved when it commits, in the same
    /// transaction as the job changes.
    /// </summary>
    OutboundMessage Send(OutboundRequest request, DateTime nowUtc);

    /// <summary>A job's outbound messages, oldest first.</summary>
    Task<IReadOnlyList<OutboundMessage>> ListForJobAsync(Guid jobId, CancellationToken cancellationToken);
}
using Meridian.Application.Abstractions;
using Meridian.Domain.Outbox;

namespace Meridian.Application.Outbox;

/// <summary>A job's outbound messages for the job view, oldest first; null when the job does not exist.</summary>
public sealed class ListOutbound
{
    private readonly IJobRepository _jobs;
    private readonly IOutbox _outbox;

    public ListOutbound(IJobRepository jobs, IOutbox outbox)
    {
        _jobs = jobs;
        _outbox = outbox;
    }

    public async Task<IReadOnlyList<OutboundMessage>?> ExecuteAsync(Guid jobId, CancellationToken cancellationToken)
    {
        if (await _jobs.GetAsync(jobId, cancellationToken) is null)
        {
            return null;
        }

        return await _outbox.ListForJobAsync(jobId, cancellationToken);
    }
}
using Meridian.Domain.Rules;

namespace Meridian.Application.Templates;

/// <summary>
/// The fixed texts sent to tenants (AD-7, RULE-5, RULE-6). The only placeholder is <c>{reference}</c>, filled with the
/// job reference; model output, addresses and tenant text are never put into a tenant message.
/// </summary>
public static class TenantTemplates
{
    public const string ReferencePlaceholder = "{reference}";

    public const string AcknowledgementId = "acknowledgement";
    public const string GasSafetyId = "gas-safety";

    public const string Acknowledgement =
        "Thank you, we have received your maintenance report. Your reference is {reference}. If anything changes or gets worse, reply to this message quoting your reference. If you smell gas, call 0800 111 999 now.";

    /// <summary>The gas safety message (RULE-6). A constant: never reworded.</summary>
    public const string GasSafety =
        "If you can smell gas or your carbon monoxide alarm is sounding: leave the property now, do not use light switches or anything electrical, do not use flames, and call the National Gas Emergency line on 0800 111 999. Your report reference is {reference}. We have been told and will contact you.";

    /// <summary>The template text for <paramref name="templateId"/>.</summary>
    public static string Text(string templateId) => templateId switch
    {
        AcknowledgementId => Acknowledgement,
        GasSafetyId => GasSafety,
        _ => throw new ArgumentOutOfRangeException(nameof(templateId), templateId, "Unknown tenant template."),
    };

    /// <summary>Renders a template with only the job reference filled in.</summary>
    public static string Render(string templateId, string reference)
    {
        if (string.IsNullOrWhiteSpace(reference))
        {
            throw new ArgumentException("A reference is required.", nameof(reference));
        }

        return Text(templateId).Replace(ReferencePlaceholder, reference, StringComparison.Ordinal);
    }

    /// <summary>
    /// The acknowledgement template for a job: <see cref="GasSafetyId"/> when the gas or carbon-monoxide rule fired,
    /// otherwise <see cref="AcknowledgementId"/>.
    /// </summary>
    public static string AcknowledgementFor(IEnumerable<string> firedRuleIds)
    {
        ArgumentNullException.ThrowIfNull(firedRuleIds);
        return firedRuleIds.Any(id => id is EmergencyRuleIds.Gas or EmergencyRuleIds.CarbonMonoxide)
            ? GasSafetyId
            : AcknowledgementId;
    }
}
namespace Meridian.Domain.Outbox;

/// <summary>Delivery state of an <see cref="OutboundMessage"/>. The first version only simulates sending (AD-8).</summary>
public enum OutboundStatus
{
    /// <summary>Stored and shown on the job; nothing left the system.</summary>
    Simulated,
}

/// <summary>Channels an outbound message can go out on.</summary>
public static class OutboundChannels
{
    public const string Email = "email";
}

/// <summary>
/// One message written to the outbox (AD-8): an acknowledgement, notification or contractor message, with the exact
/// body that was (or would be) sent. The body always comes from a fixed template (AD-7). Never updated once written.
/// </summary>
public sealed class OutboundMessage
{
    public const int MaxChannelLength = 16;
    public const int MaxTemplateIdLength = 64;

    private OutboundMessage()
    {
        Channel = string.Empty;
        Recipient = string.Empty;
        TemplateId = string.Empty;
        Body = string.Empty;
    }

    public Guid Id { get; private set; }

    public Guid JobId { get; private set; }

    /// <summary>For example <see cref="OutboundChannels.Email"/>.</summary>
    public string Channel { get; private set; }

    public string Recipient { get; private set; }

    /// <summary>The id of the fixed template the body was rendered from, e.g. <c>acknowledgement</c>.</summary>
    public string TemplateId { get; private set; }

    public string Body { get; private set; }

    public OutboundStatus Status { get; private set; }

    public DateTime CreatedAtUtc { get; private set; }

    public static OutboundMessage Create(
        Guid jobId,
        string channel,
        string recipient,
        string templateId,
        string body,
        OutboundStatus status,
        DateTime createdAtUtc)
    {
        if (jobId == Guid.Empty)
        {
            throw new ArgumentException("A job is required.", nameof(jobId));
        }

        RequireText(channel, nameof(channel), MaxChannelLength);
        RequireText(recipient, nameof(recipient), null);
        RequireText(templateId, nameof(templateId), MaxTemplateIdLength);
        RequireText(body, nameof(body), null);
        if (!Enum.IsDefined(status))
        {
            throw new ArgumentOutOfRangeException(nameof(status), status, "Unknown outbound status.");
        }

        Guards.RequireUtc(createdAtUtc, nameof(createdAtUtc));

        return new OutboundMessage
        {
            Id = Guid.NewGuid(),
            JobId = jobId,
            Channel = channel,
            Recipient = recipient,
            TemplateId = templateId,
            Body = body,
            Status = status,
            CreatedAtUtc = createdAtUtc,
        };
    }

    private static void RequireText(string value, string paramName, int? maxLength)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new ArgumentException("A value is required.", paramName);
        }

        if (maxLength is { } max && value.Length > max)
        {
            throw new ArgumentException($"Must be at most {max} characters.", paramName);
        }
    }
}
using Meridian.Application.Outbox;
using Meridian.Domain.Outbox;
using Meridian.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Meridian.Infrastructure.Outbox;

/// <summary>
/// The first version's outbox adapter (AD-8): stores each message as an <see cref="OutboundMessage"/> row with status
/// <see cref="OutboundStatus.Simulated"/> so it can be shown on the job. No email or SMS is sent.
/// </summary>
internal sealed class SimulatedOutbox : IOutbox
{
    private readonly MeridianDbContext _db;

    public SimulatedOutbox(MeridianDbContext db)
    {
        _db = db;
    }

    public OutboundMessage Send(OutboundRequest request, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(request);
        var outbound = OutboundMessage.Create(
            request.JobId,
            request.Channel,
            request.Recipient,
            request.TemplateId,
            request.Body,
            OutboundStatus.Simulated,
            nowUtc);

        // Tracked only: written when the surrounding unit of work commits, with the job changes.
        _db.OutboundMessages.Add(outbound);
        return outbound;
    }

    public async Task<IReadOnlyList<OutboundMessage>> ListForJobAsync(Guid jobId, CancellationToken cancellationToken) =>
        await _db.OutboundMessages
            .AsNoTracking()
            .Where(o => o.JobId == jobId)
            .OrderBy(o => o.CreatedAtUtc)
            .ThenBy(o => o.Id)
            .ToListAsync(cancellationToken);
}
